solutionCodeJson.code:
const FEATURES = [
 {
  "id": "F1",
  "name": "Guest checkout",
  "value": 9,
  "cost": 3,
  "risk": 2
 },
 {
  "id": "F2",
  "name": "Coupon codes",
  "value": 6,
  "cost": 4,
  "risk": 2
 },
 {
  "id": "F3",
  "name": "Crypto payment",
  "value": 4,
  "cost": 8,
  "risk": 9
 },
 {
  "id": "F4",
  "name": "Dark mode",
  "value": 3,
  "cost": 2,
  "risk": 1
 }
];

function rank(features) {
  function ok(n) { return typeof n === 'number' && n >= 1 && n <= 9; }
  return features
    .filter(function (f) { return ok(f.value) && ok(f.cost) && ok(f.risk); })
    .map(function (f, i) { return { id: f.id, priority: Math.round(f.value / (f.cost + f.risk) * 100) / 100, i: i }; })
    .sort(function (a, b) { return b.priority - a.priority || a.i - b.i; })
    .map(function (x) { return { id: x.id, priority: x.priority }; });
}
